import { activeLanguage } from '../i18n';
import { COUNTRY_EN_BY_PT, MAP_NAMES_EN, TIMETABLE_NAMES_EN } from '../i18n/catalogueNames';

/**
 * The published manifests name maps and timetables in Portuguese (`nome`, and
 * a map's `pais`); in English these give the name from
 * `src/i18n/catalogueNames.ts`, generated by `scripts/catalogue-names.py`
 * (author's request, 20 November 2026). Read when called, so a change of
 * language shows at the next render.
 */
export function mapName(region: { id: string; nome: string }): string {
  return activeLanguage() === 'en' ? MAP_NAMES_EN[region.id] ?? region.nome : region.nome;
}

/** The country a map belongs to, in the app's language (its own name without `pais`). */
export function mapCountry(region: { id: string; nome: string; pais?: string }): string {
  if (!region.pais) {
    return mapName(region);
  }
  return activeLanguage() === 'en' ? COUNTRY_EN_BY_PT[region.pais] ?? region.pais : region.pais;
}

export function timetableName(info: { id: string; nome: string }): string {
  return activeLanguage() === 'en' ? TIMETABLE_NAMES_EN[info.id] ?? info.nome : info.nome;
}
